 * including the target's per-project quota. The issue takes the target's
 * next number; its old one stays retired in the source project.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
