import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import { registerActivityListeners, listActivity } from "@/server/services/activity-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("moves", async () => {
  const off = registerActivityListeners();
  const t = await createTenant("mv");
  const p2 = await projectRepo.insertProject({ orgId: t.org.id, name: "B", slug: "b", key: "B", description: null, visibility: "org", leadId: null, color: "#000000", targetDate: null } as never);
  const a1 = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
  const a2 = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
  await issueService.createIssue(t.actors.member, issueInput(t.org.id, p2.id));
  const seen: unknown[] = [];
  const off2 = subscribe("issue.moved", (p) => { seen.push(p); });
  const moved = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: a2.id, toProjectId: p2.id });
  expect(moved.projectId).toBe(p2.id); expect(moved.number).toBe(2);
  const a3 = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
  expect(a3.number).toBe(3);
  const back = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: a2.id, toProjectId: t.project.id });
  expect(back.number).toBe(4);
  const same = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: a1.id, toProjectId: t.project.id });
  expect(same).toEqual(a1);
  expect(seen).toHaveLength(2);
  const act = await listActivity(t.actors.owner, { orgId: t.org.id, action: ["issue.moved"], limit: 50, cursor: null } as never);
  console.log(JSON.stringify(seen[0]), JSON.stringify(act.items[0]));
  await expect(issueService.moveIssueToProject(t.actors.viewer, { orgId: t.org.id, issueId: a1.id, toProjectId: p2.id })).rejects.toThrow();
  off(); off2();
});
EOF
